import {subjectQuestions,reflectionProgress,orderReflectedPathways,allSubjectOptions,subjectSuggestions,cleanReflection,subjectEvidence,subjectReviewQueue,subjectDetailQueue} from './subject-reflection.js?v=0.17.0';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,route,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="#/${route}">${text}</a>`;
const statusCopy=(state,progress)=>state?.subjectStatus==='paused'?'Your subject answers are kept. Starting points use broad interests only.':state?.subjectStatus==='broad-tie'?'These answers connect equally to many directions. Shared directions supported by at least two questions stay visible as unranked clues. You can add detail before refining the order. Broad-interest suggestions are kept.':!state?.subjectActive?(progress.directional===1?'You have one directional subject answer. Its clues stay visible separately; starting points still use broad interests. A second directional answer can refine the order.':'At least two questions with current subject directions are needed to refine the order. Starting points use broad interests when that profile is usable.')+' Unsure, skipped and unanswered responses create no preference or penalty.':state.subjectDiversified?(state.subjectDiversityBasis==='directions'?'Across more than one question, you chose two distinct study directions. We keep starting points from both, even when the choices cross broad areas.':'Your choices clearly span two study areas. We keep up to two pathways from each among the starting points, so both directions stay visible.'):'Each question adds at most one connection per pathway. More connected questions come first; broad interests break ties. Subject starting points need connections from at least two questions.';
const legacyNote=p=>p.legacy?`<p class="note">${p.legacy} earlier broad answer${p.legacy===1?' is':'s are'} still saved. Use the short review to consider only the changed questions, or keep exploring now. Earlier broad choices are not silently narrowed and do not count toward the refined order.</p>`:'';
const reviewLink=p=>p.legacy?button(`Review ${p.legacy} earlier answer${p.legacy===1?'':'s'} →`,'subjects/review',true):'';
const modeButton=state=>`<button class="text-link" data-subject-mode="${state?.subjectStatus==='paused'?'on':'off'}">${state?.subjectStatus==='paused'?'Use my subject choices again':'Compare broad interests only'}</button>`;
const detailLink=draft=>subjectDetailQueue(draft).map(x=>`<p class="note">Your explaining, listening or coaching choice is broad. If you want, <a href="#/subjects/${x.index}">add a health, learning or community detail</a>. Keeping it unchanged is fine; no detail is assumed.</p>`).join('');
function clarificationPanel(q,a){
 const parents=q.options.filter(o=>q.options.some(x=>x.clarifies===o.id));
 return parents.flatMap(parent=>{
  const family=[parent,...q.options.filter(o=>o.clarifies===parent.id)];
  if(a?.status!=='selected'||!family.some(o=>a.choices.includes(o.id)))return[];
  return [`<aside class="panel subject-clarification" aria-label="Optional detail for explaining, listening or coaching"><h2>Which part draws you in?</h2><p>Optional detail for your explaining, listening or coaching choice. Selecting a detail replaces only that choice; your other choice stays selected. You can continue with your broad answer, be unsure or skip.</p><div class="subject-options" role="group" aria-label="Optional care, learning or community detail">${family.slice(1).map(o=>`<button data-subject-question="${q.id}" data-subject-choice="${o.id}" aria-pressed="${a.choices.includes(o.id)}">${h(o.label)}<span aria-hidden="true">${a.choices.includes(o.id)?'✓':'+'}</span></button>`).join('')}</div>${!a.choices.includes(parent.id)?`<button class="text-link" data-subject-question="${q.id}" data-subject-choice="${parent.id}">Use the broad explaining, listening or coaching choice</button>`:'<p class="subtle">No detail selected. Your broad choice is still saved.</p>'}<p class="subtle">This is part of the same question. It does not add another answer or connection.</p></aside>`];
 }).join('');
}
export function subjectStrip(draft,refined=[]){const p=reflectionProgress(draft),state=refined[0];return`<aside class="profile-strip"><div><strong>Subjects I’m curious about · optional</strong><p>${p.recorded?statusCopy(state,p):'Eight original Fieldguide questions about courses and projects. No profession choice needed.'}</p>${detailLink(draft)}${p.legacy?`<p>${p.legacy} earlier broad answer${p.legacy===1?' needs':'s need'} review. They are kept but excluded from subject ordering.</p>${reviewLink(p)}`:''}</div><div><a class="text-link" href="#/subjects${p.recorded?'/summary':''}">${p.recorded?'Review my subject reflection':'Try the subject reflection'} ↗</a>${p.recorded?'<p>'+modeButton(state)+'</p>':''}</div></aside>`;}
export function pathwayReason(p){if(p.subjectActive&&p.subjectStartingPoint===false&&p.subjectConnections>=2)return `<div class="subject-reason"><strong>Another subject connection</strong><p>You chose: ${p.subjectReasons.flatMap(r=>r.labels).map(h).join(' · ')}</p><small>${p.subjectConnections} answered questions connect to this pathway. It is outside your ranked starting points and remains an unranked direction to explore.</small></div>`;if(!p.subjectActive&&p.subjectStatus==='broad-tie'&&p.subjectConnections>=2)return `<div class="subject-reason"><strong>From broad subject answers</strong><p>You chose: ${p.subjectReasons.flatMap(r=>r.labels).map(h).join(' · ')}</p><small>${p.subjectConnections} answered questions connect to this pathway. Subject ordering is deferred; this is not a subject-ranked recommendation.</small></div>`;if(!p.subjectActive&&p.subjectStatus==='needs-answers'&&p.subjectConnections)return `<div class="subject-reason"><strong>From one subject answer</strong><p>You chose: ${p.subjectReasons.flatMap(r=>r.labels).map(h).join(' · ')}</p><small>A clue to explore, not a subject-ranked recommendation. Starting points still use broad interests when available.</small></div>`;return p.subjectActive&&p.subjectConnections?`<div class="subject-reason"><strong>Why explore this?</strong><p>You chose: ${p.subjectReasons.slice(0,2).flatMap(r=>r.labels).map(h).join(' · ')}</p><small>${p.subjectConnections} question${p.subjectConnections===1?'':'s'} connect${p.subjectConnections===1?'s':''} to this pathway. This is an invitation to investigate.</small></div>`:'';}
export function stretchFor(p){
 const groups=[
  [['software','it','data'],'Try a beginner programming or data exercise. Notice how you feel about debugging, precision and trying again.'],
  [['electrical','mechanical','civil','engineering','physical'],'Try a short mathematical modeling or physics problem alongside a practical demonstration. Compare the amount of math in actual first-year courses.'],
  [['biology','environment','nursing','allied','movement','health-professional'],'Try an introductory science or evidence-based care lesson. Check lab requirements and whether later professional study would be needed.'],
  [['design','arts','architecture','media'],'Make a small piece of work, invite feedback and revise it. Check studio time, writing or portfolio expectations in the specific program.'],
  [['applied-technology','construction','transport'],'Try a supervised practical task or technical diagram. Ask about safety training, placements and the balance of workshop and classroom time.'],
  [['accounting','finance','management','marketing','hospitality'],'Try a small budget, data or planning case. Compare quantitative work, group projects and presentations in the course list.'],
  [['education','psychology','social','society','human-services','public-service'],'Try reading a short study and discussing a realistic people or community problem. Check research methods, writing and placement expectations.']
 ];
 return groups.find(([ids])=>ids.includes(p.id))?.[1]||'Try a short reading, discussion and written response. Check the specific program’s research, language, quantitative and later qualification requirements.';
}
export function sparseSubjectClues(ranked,draft){
 const e=subjectEvidence(ranked,draft);if(!e.clues.length)return'';
 if(e.clueKind==='repeated-other'||e.clueKind==='broad-repeated'){
  const broad=e.clueKind==='broad-repeated';
  const names={technology:'Computing & engineering',science:'Science & the natural world',health:'Health & human wellbeing',people:'People, learning & society',creative:'Design, arts & communication',business:'Business & public life'},areas=[...new Set(e.clues.map(p=>p.area))].sort((a,b)=>(names[a]||a).localeCompare(names[b]||b));
  return `<details class="panel subject-clues" aria-label="${broad?'Repeated connections from broad subject answers':'Other repeated subject connections'}"><summary>${broad?'Directions from your broad answers':'Other directions from your answers'} · ${e.clues.length} connected pathways</summary><p>${broad?'Your subject answers still leave a broad tie. Starting points keep their broad-interest basis. Every pathway below connects to at least two different questions; these connections do not refine that ranking.':'These directions connect to at least two different questions but sit outside your ranked starting points.'} They are unranked possibilities, grouped by broad study area and listed alphabetically. More connections do not measure ability or how strongly you like a subject.</p>${areas.map(area=>`<section><h3>${h(names[area]||area)}</h3><div class="chips">${e.clues.filter(p=>p.area===area).map(p=>`<a class="chip" data-subject-clue="${p.id}" href="#/path/${p.id}">${h(p.title)} ↗ <small>(${p.subjectConnections} questions)</small></a>`).join('')}</div></section>`).join('')}<p class="subtle">Open a pathway to review the answers behind its connection. Adding a third interest does not cancel an earlier one. You can change a choice or pause the subject lens whenever you want.</p>${broad&&e.followUp?`<div class="subject-followup"><h3>One optional follow-up</h3><p>${h(e.followUp.text)}</p><p class="subtle">This question is unanswered. Opening it selects nothing; unsure and skipped answers stay unchanged.</p>${button('Try one more question →','subjects/'+e.followUp.index)}</div>`:''}</details>`;
 }
 const tied=e.clueKind==='broad-tie' ,label=tied?'Clues from broad subject answers':'Clues from one subject answer',intro=tied?'From broad subject answers · unranked clues':'From one subject answer · unranked clues';
 const explanation=tied?'These pathways share the strongest connection across at least two of your answered questions. The answers do not separate them enough to refine the order.':'One answer is a clue, not enough to refine the starting-point order.';
 return`<section class="panel subject-clues" aria-label="${label}"><span class="eyebrow">${intro}</span><h2>Keep this curiosity in view.</h2><p>You chose: ${[...new Set(e.clues.flatMap(p=>p.subjectReasons.flatMap(r=>r.labels)))].map(h).join(' · ')}</p><p>These ${e.clues.length} connected pathways are shown alphabetically. ${explanation} Any starting points based on broad interests use a different basis.</p><div class="chips">${e.clues.map(p=>`<a class="chip" data-subject-clue="${p.id}" href="#/path/${p.id}">${h(p.title)} ↗</a>`).join('')}</div>${e.followUp?`<div class="subject-followup"><h3>One optional follow-up</h3><p>${h(e.followUp.text)}</p><p class="subtle">This unanswered question has choices connected to your curiosity. Opening it selects nothing. You can be unsure, skip or leave.</p>${button('Try one more question →','subjects/'+e.followUp.index)}</div>`:'<p class="subtle">You can revisit a question if you want to add more detail. You do not need to change an unsure or skipped answer.</p>'}</section>`;
}

function guidedReview(draft,step,ranked){
 const queue=subjectReviewQueue(draft),p=reflectionProgress(draft);
 if(step==='review')return`<div class="wrap narrow"><span class="eyebrow">Optional guided review · older answers</span><h1>${queue.length?'A short review.<br>Your choices stay yours.':'No earlier broad choices need review.'}</h1><section class="panel"><h2>${queue.length} earlier answer${queue.length===1?'':'s'} still to review</h2><p>Only questions with a replaced broad choice appear here. Your earlier labels stay saved until you explicitly edit them. Current choices, unsure, skipped and unanswered responses are left alone.</p>${legacyNote(p)}${queue.map(q=>`<div class="subject-review"><h3>${h(q.text)}</h3><p>Saved: ${q.earlier.map(o=>h(o.label)).join(' · ')}</p><a class="text-link" href="#/subjects/review-${q.id}">Review this earlier answer ↗</a></div>`).join('')}<div class="actions">${queue.length?button('Start the short review →','subjects/review-'+queue[0].id):button('See my reflection →','subjects/summary')}${button('Keep exploring; review later','pathways',true)}</div><p class="subtle">Earlier broad choices do not count toward the current subject order. You can keep them and continue. Your official interests, lifestyle goal and shortlist are retained.</p></section></div>`;
 const id=step.slice('review-'.length),q=subjectQuestions.find(q=>q.id===id&&q.legacyOptions.length);
 if(!q)return subjectPage(draft,'invalid',ranked);
 const index=subjectQuestions.indexOf(q),pending=queue.some(x=>x.id===id),next=queue.find(x=>x.index>index);
 const page=subjectPage(draft,String(index),ranked),start=page.indexOf('<div class="actions">');
 return page.slice(0,start)+`<aside class="note" role="status">Guided review · ${queue.length} earlier answer${queue.length===1?' remains':'s remain'}. ${pending?'Your earlier choice is still saved. Deselect it before replacing it, or keep it for later.':'This question no longer contains an earlier broad choice. '+(draft.answers[q.id]?'Your explicit answer is saved.':'It is now unanswered; no preference is inferred.')}</aside><div class="actions">${button(pending?'Keep earlier answer & continue →':'Continue review →',next?'subjects/review-'+next.id:'subjects/review')}${button('Keep exploring; review later','pathways',true)}</div><p><a href="#/subjects/review">← Review list</a></p></div>`;
}
export function subjectPage(draft,step,ranked,{sample=false}={}){
 if(step==='review'||step?.startsWith('review-'))return guidedReview(draft,step,ranked);
 const p=reflectionProgress(draft),intro=`<span class="eyebrow">Original Fieldguide reflection · optional</span>`;
 if(step===undefined)return`<div class="wrap narrow"><section class="page-intro">${intro}<h1>Which subjects<br>make you curious?</h1><p class="lede">Try eight short questions about courses, projects and learning experiences. Keep up to two choices per question. You can be unsure, skip or stop anytime.</p></section><section class="panel"><h2>Another way to find a beginning</h2><p>This is separate from the official O*NET Interest Profiler. These original prompts are an exploratory prototype, not a validated assessment of ability or future success.</p><p>After two questions with current subject directions, connected pathways can become starting points. When broad answers tie many pathways, we keep the broad-interest view unless repeated, explicitly selected directions support a balanced set. Multiple clearly selected areas can stay visible together. All 36 pathways stay open, and your shortlist and lifestyle goal stay yours.</p><p class="subtle">${sample?'Sample choices last in this tab only; reloading restarts Jordan’s journey.':'Choices save in this browser for Approach 2 and are included in a full draft export.'}</p><div class="actions">${button(p.recorded?'Review my choices →':'Try the eight questions →','subjects/0')}${button('Continue without this','pathways',true)}</div>${reviewLink(p)}${sample?'<hr><p>Jordan’s original 60 interest answers and lifestyle choices are already loaded. The new subject reflection starts empty.</p><button class="button secondary" data-subject-sample>Try Jordan’s fictional subject choices</button>':''}</section></div>`;
 if(step==='summary'){
  const refined=orderReflectedPathways(ranked,draft),state=refined[0],active=!!state?.subjectActive;
  return`<div class="wrap"><section class="page-intro">${intro}<h1>A few clues.<br>Room to explore.</h1><p class="lede">${p.substantive} of 8 questions have selected choices · ${p.unsure} unsure · ${p.skipped} skipped · ${8-p.recorded} unanswered.</p></section><section class="panel"><h2>${active?'Starting points from your course and project choices':'Keep exploring at your own pace'}</h2><p>${statusCopy(state,p)} No choice is a test of ability.</p>${legacyNote(p)}${reviewLink(p)}${detailLink(draft)}${sparseSubjectClues(ranked,draft)}<div class="actions">${modeButton(state)}</div>${active?`<div class="subject-starting-grid">${subjectSuggestions(refined).map(x=>`<article><h3><a href="#/path/${x.id}">${h(x.title)} ↗</a></h3>${pathwayReason(x)}</article>`).join('')}</div>`:''}<div class="actions">${button('Explore college pathways →','pathways')}${button('Compare my shortlist','compare',true)}</div><p class="subtle">Refining suggestions does not change your saved shortlist. Earnings do not influence this order.</p></section><details class="panel" open><summary>Review all eight original questions</summary>${subjectQuestions.map((q,i)=>{const a=draft.answers[q.id];return`<div class="subject-review"><h3>${i+1}. ${h(q.text)}</h3><p>${a?.status==='selected'?allSubjectOptions(q).filter(o=>a.choices.includes(o.id)).map(o=>h(o.label)+(q.legacyOptions.includes(o)?' (earlier broad choice; review)':'')).join(' · '):a?.status==='unsure'?'Not sure yet':a?.status==='skipped'?'Skipped':'Not answered'}</p><a class="text-link" href="#/subjects/${i}">Edit this answer ↗</a></div>`;}).join('')}<button class="text-link" data-subject-clear>Clear only subject reflection</button></details><p class="subtle"><a href="#/about">How suggestions work & editorial mappings ↗</a></p></div>`;
 }
 const i=Number(step),q=Number.isInteger(i)&&i>=0&&String(i)===String(step)?subjectQuestions[i]:null;
 if(!q)return`<div class="wrap narrow"><h1>That question isn’t available.</h1>${button('Open the subject reflection','subjects')}</div>`;
 const a=draft.answers[q.id],earlier=q.legacyOptions.filter(o=>a?.status==='selected'&&a.choices.includes(o.id));
 return`<div class="wrap narrow subject-question">${intro}<p class="subtle">Question ${i+1} of 8 · ${p.recorded} recorded</p><h1>${h(q.text)}</h1><p id="subject-help">Choose up to two. Pick what you would like to try, even if you haven’t studied it yet.</p>${earlier.length?`<aside class="panel"><h3>Your saved earlier choice</h3><p>This broader option was replaced with clearer choices. It stays saved until you change it. Deselect it to make room for a more specific choice.</p><div class="subject-options">${earlier.map(o=>`<button data-subject-question="${q.id}" data-subject-choice="${o.id}" aria-pressed="true">${h(o.label)}<span aria-hidden="true">✓</span></button>`).join('')}</div></aside>`:''}<div class="subject-options" role="group" aria-describedby="subject-help" aria-label="Course and project choices">${q.options.filter(o=>!o.clarifies).map(o=>`<button data-subject-question="${q.id}" data-subject-choice="${o.id}" aria-pressed="${a?.status==='selected'&&a.choices.includes(o.id)}">${h(o.label)}<span aria-hidden="true">${a?.status==='selected'&&a.choices.includes(o.id)?'✓':'+'}</span></button>`).join('')}</div>${clarificationPanel(q,a)}<div class="subject-unknown"><button class="chip" data-subject-question="${q.id}" data-subject-choice="unsure" aria-pressed="${a?.status==='unsure'}">Not sure yet</button><button class="chip" data-subject-question="${q.id}" data-subject-choice="skipped" aria-pressed="${a?.status==='skipped'}">Skip this question</button></div><p class="subtle" role="status">${a?.status==='selected'?`${a.choices.length} of 2 choices selected.`:a?.status==='unsure'?'Marked unsure. This adds no preference.':a?.status==='skipped'?'Skipped. This adds no preference.':'No answer yet. You can leave it unanswered.'}</p><div class="actions">${button(i===7?'See my reflection →':'Continue →',i===7?'subjects/summary':'subjects/'+(i+1))}${button('Pause & see my reflection','subjects/summary',true)}</div><p><a href="#/subjects${i?'/'+(i-1):''}">← ${i?'Previous question':'Introduction'}</a></p></div>`;
}
export function subjectMethod(paths){return`<section class="panel"><h3>Optional subject reflection: a second lens</h3><p>The eight course and project questions are original Fieldguide editorial content, not O*NET questions or a validated assessment. Select up to two options per question. Unsure, skipped and missing answers are unknown; they contribute nothing and incur no penalty.</p><p>At least two questions with current, pathway-connected choices are needed. Each question contributes at most one connection per pathway. Current connection counts order starting points, with broad-interest order breaking ties (alphabetically without a usable interest profile). General evidence/reasoning preferences do not identify a subject direction. Earlier broad options stay saved and readable, but require review rather than being silently narrowed.</p><p>If more than four pathways share the largest connection count, subject ordering is deferred unless repeated explicit mixed-area or distinct-direction evidence supports a balanced set. The broad-interest order remains available. Subject starting points contain only pathways connected to at least two questions; fewer than four can be shown.</p><p>Mixed-area evidence requires at least two questions where two selected current options each connect to a different single broad study area. We take the two areas supported by the most such questions (area ID breaks any remaining tie), and keep up to two pathways connected to at least two questions from each among the first few. Within that set, connection count and broad-interest order apply. When this two-area rule does not apply, we also look for two distinct directions explicitly selected together in at least two different questions. We intersect the option-to-pathway sets across those questions, remove any overlap between the two resulting groups, and keep only pathways with at least two connected questions. We select the pair supported by the most two-choice questions, then the strongest minimum connection count across the groups, then the total of those two strongest counts; canonical pathway IDs break remaining ties. Up to two pathways from each group stay among the starting points, in connection-count and broad-interest order. One two-choice question cannot trigger this rule. If this balanced set would omit every pathway with the globally largest connection count, one strongest pathway is restored by replacing the weakest selected member of a group that still has another representative. Connection count and broad-interest tie order still apply. This is an editorial exploration rule, not calibrated outcome prediction. All pathways remain accessible.</p><p>When broad answers leave more than four pathways tied at the largest connection count, all those tied pathways stay visible separately as alphabetical, unranked clues if each connects to at least two questions. This adds no ranking or inferred answer; broad-interest starting points are unchanged. If the broad tie also leaves weaker connections supported by at least two questions, every repeated connection remains available together in a closed, grouped, unranked collection. Connection counts never assign ability or priority. A tie at only one connected question adds no broad-tie clue panel.</p><p>With an active subject lens, other pathways connected to at least two distinct questions remain available in a closed, grouped disclosure outside the ranked starting points. They are unranked, and every qualifying pathway is included. A one-question connection does not create a repeated clue. Pausing hides this collection without deleting answers. Selection frequency does not measure intensity of preference or ability; adding a third positive interest creates no negative-interest penalty.</p><p>These mappings are exploratory and not calibrated across subjects. Neither pay, lifestyle costs, occupation counts nor program counts enter the order. The subject lens can be paused without clearing answers, and never changes the saved shortlist. With just one directional answer, its connected pathways appear separately as alphabetical, unranked clues. Starting points retain their broad-interest basis; a relevant unanswered question may be offered, without any selected response. Guided review includes only questions still containing earlier broad choices, and can be deferred without clearing them.</p><p>Three additional optional project/practice choices distinguish learning activities, community-service access and hospitality service study. Their mappings are Fieldguide editorial choices informed by the scope of <a href="https://nces.ed.gov/ipeds/cipcode/cipdetail.aspx?cipid=90410&y=56" target="_blank" rel="noopener">NCES education</a>, <a href="https://nces.ed.gov/ipeds/cipcode/cipdetail.aspx?cipid=90848&y=56" target="_blank" rel="noopener">social work</a> and <a href="https://nces.ed.gov/ipeds/cipcode/cipdetail.aspx?cipid=91194&y=56" target="_blank" rel="noopener">hospitality</a> program descriptions. They are not official assessment items.</p><p>The explaining, listening or coaching practice choice has three optional details: health communication, learning support and community services. Details appear only after choosing that broad answer, replace only that choice and still count as the same question. Keeping the broad choice infers no narrower intent. These are editorial mappings; the health scope is informed by <a href="https://nces.ed.gov/ipeds/cipcode/cipdetail.aspx?cipid=89920&y=56" target="_blank" rel="noopener">NCES health sciences</a>. No detail changes the official Interest Profiler or earnings calculations.</p><details><summary>Inspect all current prompts and option-to-pathway mappings</summary>${subjectQuestions.map(q=>`<h4>${h(q.text)}</h4><ul>${q.options.map(o=>`<li>${h(o.label)}${o.clarifies?' (optional detail of explaining, listening or coaching)':''} → ${o.paths.length?o.paths.map(id=>h(paths.find(p=>p.id===id)?.title||id)).join('; '):'General reasoning preference; no specific study direction inferred'}</li>`).join('')}</ul>${q.legacyOptions.length?`<p>Earlier options kept for draft review only: ${q.legacyOptions.map(o=>h(o.label)).join('; ')}.</p>`:''}`).join('')}</details></section>`;}
